<!DOCTYPE html>
<html>
<body>
<p>Prime numbers between 1 and 100 (excluding prime numbers with specific digit):</p>
<ul id="prime-list"></ul>
<script>
function isPrime(num) {
  if (num <= 1) return false;
  for (var i = 2; i <= Math.sqrt(num); i++) {
    if (num % i == 0) return false;
  }
  return true;
}
function digitPrime(num) {
  var digits = num.toString().split('');
  for (var i = 0; i < digits.length; i++) {
    if (isPrime(Math.sqrt(parseInt(digits[i])))) {
      return true;
    }
  }
  return false;
}
var primeList = [];
for (var i = 2; i <= 100; i++) {
  if (isPrime(i) && !digitPrime(i)) {
    primeList.push(i);
  }
}
var primeListElem = document.getElementById("prime-list");
for (var i = 0; i < primeList.length; i++) {
  var li = document.createElement("li");
  li.appendChild(document.createTextNode(primeList[i]));
  primeListElem.appendChild(li);
}
</script>
</body>
