```
import java.util.*;
class Person {
    private String name;
    private String address;
    private String email;
    private String code;
    public Person(String name, String address, String email) {
        this.name = name;
        this.address = address;
        this.email = email;
        this.code = generateCode(name, address, email);
    }
    public String getName() {
        return name;
    }
    public String getAddress() {
        return address;
    }
    public String getEmail() {
        return email;
    }
    public String getCode() {
        return code;
    }
    public void setName(String name) {
        this.name = name;
        this.code = generateCode(name, address, email);
    }
    public void setAddress(String address) {
        this.address = address;
        this.code = generateCode(name, address, email);
    }
    public void setEmail(String email) {
        this.email = email;
        this.code = generateCode(name, address, email);
    }
    private String generateCode(String name, String address, String email) {
        String code = "";
        code += name.charAt(0);
        code += name.charAt(name.lastIndexOf(" ") + 1);
        code += address.replaceAll("\\D+","");
        code += email.substring(0, 2);
        code = code.toUpperCase();
        return code;
    }
}
public class RoadTrip {
    public static void main(String[] args) {
        List<Person> people = new ArrayList<>();
        people.add(new Person("John Smith", "123 Main St", "johnsmith@email.com"));
        people.add(new Person("Jane Doe", "456 Oak St", "janedoe@email.com"));
