        for (Person person : people) {
            System.out.println(person.getName() + "\t" + person.getAddress() + "\t" + person.getEmail() + "\t" + person.getCode());
        }
        Collections.sort(people, Comparator.comparing(Person::getCode));
        System.out.println("\nSorted table:");
        System.out.println("Name\t\tAddress\t\t\t\tEmail\t\t\t\tCode");
        for (Person person : people) {
            System.out.println(person.getName() + "\t" + person.getAddress() + "\t" + person.getEmail() + "\t" + person.getCode());
        }
        // Update a person's information
