  .attr("d", arc)
  .style("fill", function(d) {
    return color(d.data);
  });
g.append("text")
  .attr("transform", function(d) {
    return "translate(" + arc.centroid(d) + ")";
  })
  .attr("dy", ".35em")
  .text(function(d) {
    return d.data;
  });
```
