What would be the Swift code to categorize the given items based on both season and geographic location? Here is the list of items: 
- Apple
- Pumpkin
- Watermelon
- Onion
We want to categorize them based on the following criteria: 
- Season (i.e., when the items are typically harvested)
- Geographic Location (i.e., where the items are commonly grown)
Here's the Swift code to categorize the items based on the given criteria:
struct Item {
    var name: String
    var season: String
    var location: String
}
let apple = Item(name: "Apple", season: "Fall", location: "North America")
let pumpkin = Item(name: "Pumpkin", season: "Fall", location: "North America")
let watermelon = Item(name: "Watermelon", season: "Summer", location: "Tropical Regions")
let onion = Item(name: "Onion", season: "Spring/Summer", location: "Worldwide")
let items = [apple, pumpkin, watermelon, onion]
// Categorize by season
let fallItems = items.filter { $0.season == "Fall" }
let summerItems = items.filter { $0.season == "Summer" }
let springSummerItems = items.filter { $0.season == "Spring/Summer" }
// Categorize by location
let northAmericaItems = items.filter { $0.location == "North America" }
let tropicalRegionItems = items.filter { $0.location == "Tropical Regions" }
let worldwideItems = items.filter { $0.location == "Worldwide" }
// Display the categorized items
