for item in fallItems {
    print("- " + item.name)
}
print("Summer items: ")
for item in summerItems {
    print("- " + item.name)
}
print("Spring/Summer items: ")
for item in springSummerItems {
    print("- " + item.name)
}
print("North America items: ")
for item in northAmericaItems {
    print("- " + item.name)
}
print("Tropical Region items: ")
for item in tropicalRegionItems {
    print("- " + item.name)
}
print("Worldwide items: ")
for item in worldwideItems {
    print("- " + item.name)
}

