```c++
#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;
// Define a struct to hold information about each expense
struct Expense {
    string name;
    double amount;
};
// Define a function to compare expenses based on their amounts
bool compare_expenses(const Expense& e1, const Expense& e2) {
    return e1.amount > e2.amount;
}
int main() {
    // Define variables to hold earnings and expenses
    double earnings = 0;
    vector<Expense> expenses;
    // Prompt the user to enter earnings and expenses
    cout << "Enter your earnings: ";
    cin >> earnings;
    cout << "Enter your expenses (enter a negative amount to stop):\n";
    while (true) {
        string name;
        double amount;
        cout << "Name of expense: ";
        cin >> name;
        if (name.empty()) break;
        cout << "Amount of expense: ";
        cin >> amount;
        if (amount < 0) break;
        expenses.push_back({name, amount});
    }
    // Sort expenses in descending order of amount
    sort(expenses.begin(), expenses.end(), compare_expenses);
    // Calculate total expenses
    double total_expenses = 0;
    for (const auto& expense : expenses) {
        total_expenses += expense.amount;
    }
    // Calculate remaining income after expenses
    double remaining_income = earnings - total_expenses;
    // Print a summary of expenses and remaining income
    cout << "Expenses:\n";
    for (const auto& expense : expenses) {
        cout << expense.name << ": $" << expense.amount << endl;
    }
    cout << "Total expenses: $" << total_expenses << endl;
    cout << "Remaining income: $" << remaining_income << endl;
    // Look for opportunities to reduce expenses
    for (auto& expense : expenses) {
        if (remaining_income >= expense.amount) {
            cout << "You could reduce your " << expense.name << " expense by $" << expense.amount << endl;
            remaining_income -= expense.amount;
            expense.amount = 0;
        } else if (remaining_income > 0) {
