Certainly! Here's an implementation of merge sort in C++ that should handle sorting a large number of duplicate elements while preserving their order:
```c++
#include <iostream>
#include <vector>
using namespace std;
void merge(vector<int>& arr, int l, int m, int r) {
    int n1 = m - l + 1;
    int n2 = r - m;
    vector<int> L(n1);
    vector<int> R(n2);
    for (int i = 0; i < n1; i++) {
        L[i] = arr[l + i];
    }
    for (int j = 0; j < n2; j++) {
        R[j] = arr[m + 1 + j];
    }
    int i = 0;
    int j = 0;
    int k = l;
    while (i < n1 && j < n2) {
        if (L[i] <= R[j]) {
            arr[k] = L[i];
            i++;
        }
        else {
            arr[k] = R[j];
            j++;
        }
        k++;
    }
    while (i < n1) {
        arr[k] = L[i];
        i++;
        k++;
    }
    while (j < n2) {
        arr[k] = R[j];
        j++;
        k++;
    }
}
void mergeSort(vector<int>& arr, int l, int r) {
    if (l < r) {
        int m = l + (r - l) / 2;
        mergeSort(arr, l, m);
        mergeSort(arr, m + 1, r);
        merge(arr, l, m, r);
    }
}
int main() {
    vector<int> arr = { 3, 5, 2, 8, 2, 5, 3, 9 };
    int n = arr.size();
    mergeSort(arr, 0, n - 1);
    for (int i = 0; i < n; i++) {
        cout << arr[i] << " ";
    }
    cout << endl;
    return 0;
}
```
In this implementation, the `merge` function takes care of merging two sorted subarrays into one sorted array. The `mergeSort` function recursively sorts the left and right halves of the input array, and then merges them using the `merge` function.
To handle duplicates while preserving their order, we simply use the less-than-or-equal-to operator (`<=`) instead of the less-than operator (`<`) when comparing elements in the `merge` function. This ensures that duplicates are placed in the same order in the output array as they were in the input array.
