```
import scala.io.Source
import scala.util.Try
object PriceComparison {
  def main(args: Array[String]): Unit = {
    val stores = List("convenience_store1", "convenience_store2", "supermarket1", "supermarket2")
    val brands = List("Coca-Cola", "Pepsi", "Sprite", "Dasani", "Aquafina", "Nestle Pure Life")
    val data = stores.flatMap(store => {
      brands.flatMap(brand => {
        extractData(store, brand)
      })
    })
    val prices = data.groupBy(_._1).mapValues(_.map(_._2))
    prices.foreach(p => {
      println(s"${p._1}: ${p._2.mkString(", ")}")
    })
  }
  def extractData(store: String, brand: String): List[(String, Double)] = {
    val url = s"https://$store.com/$brand/prices"
    val data = Try(Source.fromURL(url).getLines().toList)
    data.getOrElse(List.empty).flatMap(line => {
      val values = line.split(",")
      if (values.length == 2) {
        Try(values(1).toDouble).toOption.map(price => (store, price))
      } else {
        None
      }
    })
  }
}
```
