    {
        // Find the component with the specified name.
        for (int i = 0; i < pmc.PrivateUsage; i++)
        {
            if (strstr(pmc.pProcessMemoryCounter[i].szComponent, componentName))
            {
                printf("Memory used by %s: %ld\n", componentName, pmc.pProcessMemoryCounter[i].ByteUsage);
                break;
            }
        }
    }
    // Close the handle.
