string myString = "racecarannakayaklevel";
int maxLength = 0;
string longestPalindrome = "";
for (int i = 0; i < myString.Length; i++)
{
    // Check for odd-length palindromes
    for (int j = 0; i - j >= 0 && i + j < myString.Length; j++)
    {
        if (myString[i - j] != myString[i + j])
        {
            break;
        }
        int length = 2 * j + 1;
        if (length > maxLength)
        {
            maxLength = length;
            longestPalindrome = myString.Substring(i - j, length);
        }
    }
    // Check for even-length palindromes
    for (int j = 0; i - j >= 0 && i + j + 1 < myString.Length; j++)
    {
        if (myString[i - j] != myString[i + j + 1])
        {
            break;
        }
        int length = 2 * j + 2;
        if (length > maxLength)
        {
            maxLength = length;
            longestPalindrome = myString.Substring(i - j, length);
        }
    }
}
