To analyze the tone and pitch of a person's voice, you can use the open-source library Praat. Here's an example code snippet to get you started:
```java
import java.io.File;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import org.apache.commons.math3.stat.descriptive.DescriptiveStatistics;
import org.jfree.chart.ChartFactory;
import org.jfree.chart.ChartUtilities;
import org.jfree.chart.JFreeChart;
import org.jfree.data.xy.XYSeries;
import org.jfree.data.xy.XYSeriesCollection;
import ca.phon.praat.*;
public class VoiceAnalyzer {
    public static void main(String[] args) throws IOException {
        // Load the audio file
        Sound sound = new Sound(new File("audio.wav"));
        // Create a pitch object and extract the pitch contour
        Pitch pitch = sound.toPitch();
        double[] pitchContour = pitch.getContour();
        // Create a spectrogram object and extract the spectral envelope
        Spectrogram spectrogram = sound.toSpectrogram(0.01, 50, 0.005, 0.5, 20, true, Window.get(Window.HAMMING), true);
        double[] spectralEnvelope = spectrogram.getSpectralEnvelope(0.0, 5000.0, 0.1, 0.025, 50.0, 0.1, 0.025, 0.1);
        // Create a list of pitch and spectral envelope values
        List<Double> pitchValues = new ArrayList<Double>();
        List<Double> spectralEnvelopeValues = new ArrayList<Double>();
        for (int i = 0; i < pitchContour.length; i++) {
            pitchValues.add(pitchContour[i]);
            spectralEnvelopeValues.add(spectralEnvelope[i]);
        }
        // Calculate the mean, standard deviation, minimum, and maximum values for pitch and spectral envelope
        DescriptiveStatistics pitchStats = new DescriptiveStatistics();
        for (Double pitchValue : pitchValues) {
            pitchStats.addValue(pitchValue);
        }
        DescriptiveStatistics spectralEnvelopeStats = new DescriptiveStatistics();
        for (Double spectralEnvelopeValue : spectralEnvelopeValues) {
            spectralEnvelopeStats.addValue(spectralEnvelopeValue);
        }
        double pitchMean = pitchStats.getMean();
        double pitchStdDev = pitchStats.getStandardDeviation();
        double pitchMin = pitchStats.getMin();
        double pitchMax = pitchStats.getMax();
        double spectralEnvelopeMean = spectralEnvelopeStats.getMean();
        double spectralEnvelopeStdDev = spectralEnvelopeStats.getStandardDeviation();
        double spectralEnvelopeMin = spectralEnvelopeStats.getMin();
        double spectralEnvelopeMax = spectralEnvelopeStats.getMax();
        // Create a chart to visualize the pitch and spectral envelope values
        XYSeries pitchSeries = new XYSeries("Pitch");
        for (int i = 0; i < pitchValues.size(); i++) {
            pitchSeries.add(i, pitchValues.get(i));
        }
        XYSeries spectralEnvelopeSeries = new XYSeries("Spectral Envelope");
        for (int i = 0; i < spectralEnvelopeValues.size(); i++) {
            spectralEnvelopeSeries.add(i, spectralEnvelopeValues.get(i));
        }
        XYSeriesCollection dataset = new XYSeriesCollection();
        dataset.addSeries(pitchSeries);
        dataset.addSeries(spectralEnvelopeSeries);
        JFreeChart chart = ChartFactory.createXYLineChart(
            "Pitch and Spectral Envelope",
            "Time (s)",
            "Value",
            dataset
        );
        ChartUtilities.saveChartAsPNG(new File("chart.png"), chart, 800, 600);
    }
}
