As for the brain teaser, here's a recursive function in Python that can determine if two integers are relatively prime and output their prime factorization and the number of distinct prime factors they share:
```python
def prime_factors(n, factors=set()):
    for i in range(2, int(n**0.5)+1):
        if n % i == 0:
            factors.add(i)
            return prime_factors(n//i, factors)
    if n > 1:
        factors.add(n)
    return factors
def num_distinct_prime_factors(n):
    return len(prime_factors(n))
def are_relatively_prime(a, b):
    if a == 1 or b == 1:
        return True
    if a % b == 0 or b % a == 0:
        return False
    return are_relatively_prime(a, b % a)
a = 14
