      {"title": "Movie 1", "releaseYear": 2020, "director": "Director 1", "description": "Description 1"},
      {"title": "Movie 2", "releaseYear": 2019, "director": "Director 2", "description": "Description 2"},
      {"title": "Movie 3", "releaseYear": 2018, "director": "Director 3", "description": "Description 3"}
    ]"""
    val movies = Json.parse(movieJson).as[List[Movie]]
    Ok(views.html.index(movies))
  }
}
Finally, create a view to display the movie data:
@(movies: List[Movie])
@for(movie <- movies) {
  <div class="movie">
    <h2>@movie.title (@movie.releaseYear)</h2>
    <p>Director: @movie.director</p>
    <p>Description: @movie.description</p>
  </div>
}
To add a search bar, you can use JavaScript to filter the movie data based on user input.

